from bisect import bisect_left
from functools import cache
from typing import List
DEBUG = False

class Solution:
    def subarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        endOf = [0] * n # for debug
        endOfGroup = {}
        
        sum = 0
        for i in range(n):
            sum += nums[i]
            endOf[i] = sum

            endOfGroup.setdefault(sum, [])
            endOfGroup[sum].append(i)

        groupKeys = list(endOfGroup.keys())
        if k != 0:
            groupKeys.sort()

        if DEBUG:
            print(f"nums={nums} k={k}")
            print(f"    endOf={endOf}")
            print(f"    endOfGroup={endOfGroup}")
            print(f"    groupKeys={groupKeys}")


        def findGroupKey2(keyVal):
            # implement using bisect
            idx = bisect_left(groupKeys, keyVal)
            if idx < len(groupKeys) and groupKeys[idx] == keyVal:
                return idx
            return -1

        result = 0
        if k == 0: 
            for grpKey in groupKeys:
                ends = endOfGroup[grpKey]
                if grpKey == 0:
                    result += len(ends)
                result += ( len(ends) * (len(ends)-1) // 2 )
            return result        


        grpKeyIdx = findGroupKey2(k)
        if grpKeyIdx>=0: # endOf[x] == k directly
            ends = endOfGroup[groupKeys[grpKeyIdx]] 
            result += len(ends)

        # compare groupKeys[x] and groupKeys[y]
        if len(groupKeys) > 1:            
            lo = 0
            while lo +1 < len(groupKeys):
                hi = lo + 1
                
                while  hi<len(groupKeys) and groupKeys[hi] - groupKeys[lo] < abs(k):
                    hi += 1

                if hi<len(groupKeys) and groupKeys[hi] - groupKeys[lo] == abs(k):
                    if k > 0:
                        end_hi = endOfGroup[groupKeys[hi]]
                        end_lo = endOfGroup[groupKeys[lo]]
                    else:
                        end_hi = endOfGroup[groupKeys[lo]]
                        end_lo = endOfGroup[groupKeys[hi]]

                    # merge sort end_lo, end_hi
                    idx_lo = 0
                    idx_hi = 0

                    end_lo_picked = 0
                    while idx_lo < len(end_lo) and idx_hi < len(end_hi):
                        if end_lo[idx_lo] < end_hi[idx_hi]:
                            idx_lo += 1
                            end_lo_picked += 1
                        else:
                            idx_hi += 1   
                            result += end_lo_picked
                    if idx_hi < len(end_hi):
                        result += end_lo_picked * (len(end_hi)-idx_hi)        
                lo += 1


        return result

if __name__ == "__main__":
    import time

    sol = Solution()

    def computeExpected(nums, k):
        # compute expected using brute force
        n = len(nums)
        count = 0
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j]
                if s == k:
                    count += 1
        return count
